import java.util.Scanner;
public class JCheckProductCode2 {
	public static void main(String[] args) {
		JCheckProductCode2 p2 = new JCheckProductCode2();
		p2.checkProductCode();
	}
	//Khutwa 1: taerif al-dala
	public void checkProductCode() {
		//Khutwa 1.1: taerif al-mutaghayyirat alati nahtajuha lil-ihsa
	    int valid = 0;
	    int banned = 0;
	    //Khutwa 1.2: talab idkhal sahih madam al-mustakhdim la yadkhul STOP; wa ghair dhalik tawqif
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil ramz al-muntaj:");
		String code = scan.next();	    
	    while ( ! code.equals("STOP") ) {
	    	 //Khutwa 1.2.1: hawwi al-kod alladhi qad yurmi istithna dakhil blok try
	        try {
	            char zone = code.charAt(9);
	            int district = Integer.parseInt(code.substring(3, 7));
	            valid += 1;
	            if (zone == 'R' && district >= 2000) {
	                banned += 1;
	            }
	        }
	        //Khutwa 1.2.2: taamal ma'a jami al-istithnaat al-mumkin an turfa fi blok try 
	       catch (IndexOutOfBoundsException ex ) {                    
	            System.out.println("Toul al-ramz ghayr sahih.");
	       } 
		catch (NumberFormatException ex ) {                   
			System.out.println("Khata! al-maqataa laysat raqamiyya.");
		}
			System.out.println("Adkhil ramz al-muntaj:");
			code = scan.next();
	    }
	    //Khutwa 1.3: izhar al-nateeja    
	    System.out.println("# adad al-ramuz al-saliha al-madkhula: " + valid);
	    System.out.println("# adad al-ramuz al-mahzura al-madkhula: "+ banned);
	}
}
